#include <stdio.h>
#include <stdlib.h>

#define MAX_SIZE 10000

/** 并查集定义 **/
typedef struct {
    int *fa;
    int count;
} UFS;

UFS *new_UFS(int n) {
    UFS *ufs = (UFS *) malloc(sizeof(UFS));

    ufs->fa = (int *) malloc(sizeof(int) * n);
    for (int i = 0; i < n; i++) {
        ufs->fa[i] = i;
    }

    ufs->count = n;

    return ufs;
}

int find_UFS(UFS *ufs, int x) {
    if (x != ufs->fa[x]) {
        ufs->fa[x] = find_UFS(ufs, ufs->fa[x]);
        return ufs->fa[x];
    }
    return x;
}

void union_UFS(UFS *ufs, int x, int y) {
    int x_fa = find_UFS(ufs, x);
    int y_fa = find_UFS(ufs, y);

    if (x_fa != y_fa) {
        ufs->fa[y_fa] = x_fa;
        ufs->count--;
    }
}

/** 算法逻辑 **/
char matrix[MAX_SIZE][MAX_SIZE];

int main() {
    int n = 0;

    while (scanf("%[^\\,\n]", matrix[n++])) {
        if (getchar() != ',') break;
    }

    UFS *ufs = new_UFS(n);

    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            if (matrix[i][j] == '1') {
                union_UFS(ufs, i, j);
            }
        }
    }

    printf("%d\n", ufs->count);

    return 0;
}
